class Solution {
    public int minCost(int n,int[] cuts){
        int[] positions=new int[cuts.length+2];
        positions[0]=0;
        positions[positions.length-1]=n;
        System.arraycopy(cuts,0,positions,1,cuts.length);
        Arrays.sort(positions);
        int size=positions.length;
        int[][] dp=new int[size][size];
        for(int span=2;span<size;span++)for(int left=0;left+span<size;left++){
            int right=left+span;
            dp[left][right]=Integer.MAX_VALUE;
            for(int middle=left+1;middle<right;middle++)dp[left][right]=Math.min(dp[left][right],positions[right]-positions[left]+dp[left][middle]+dp[middle][right]);
        }
        return dp[0][size-1];
    }
}

